import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import { istDateStr } from "../_shared/ist_date.ts";
import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
import { logCronEnd, logCronStart } from "../_shared/cron_telemetry.ts";
import { fetchAllByIds, fetchAllPages } from "../_shared/paged_fetch.ts";
import { excludeDeletedLogs, liveLogsForWindow } from "./live_log_filter.ts";
import { completedDayCounts, mergeMonotonicTotal } from "./completed_days.ts";
import { buildDayMap, istDatesEnding, windowLogIds } from "../_shared/exercise_day.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

interface WorkoutLog {
  user_id: string;
  exercise_id: string;
  exercise_name: string;
  weight_kg: number | null;
  reps: number | null;
  completed_at: string;
  date: string; // the RESOLVED workout day (IST), not the write time
}

interface ScheduledWorkout {
  user_id: string;
  status: string;
  scheduled_date: string;
}

/**
 * Calculates experience level based on 4 weeks of workout data.
 *
 * Scoring:
 * - Weight progression: Did they increase weight on key exercises? (0-25)
 * - Completion rate: Workouts done / planned (0-25)
 * - Exercise variety: Unique exercises used (0-25)
 * - Consistency: How many of the 4 weeks had at least 1 workout (0-25)
 *
 * Total: 0-100
 * beginner: 0-39, intermediate: 40-69, advanced: 70-100
 */
function calculateExperienceLevel(
  logs: WorkoutLog[],
  scheduled: ScheduledWorkout[],
): string {
  if (logs.length === 0) return "beginner";

  // --- Weight Progression Score (0-25) ---
  // Group logs by exercise, check if weight increased over the 4 weeks
  const exerciseWeights: Record<string, { date: string; weight: number }[]> = {};
  for (const log of logs) {
    if (log.weight_kg && log.weight_kg > 0) {
      const key = log.exercise_id ?? log.exercise_name;
      if (!exerciseWeights[key]) exerciseWeights[key] = [];
      exerciseWeights[key].push({ date: log.date, weight: log.weight_kg });
    }
  }

  let progressingExercises = 0;
  let totalWeightedExercises = 0;
  for (const entries of Object.values(exerciseWeights)) {
    if (entries.length < 2) continue;
    totalWeightedExercises++;
    const sorted = entries.sort(
      (a, b) => new Date(a.date).getTime() - new Date(b.date).getTime(),
    );
    const firstWeight = sorted[0].weight;
    const lastWeight = sorted[sorted.length - 1].weight;
    if (lastWeight > firstWeight) progressingExercises++;
  }

  const progressionScore =
    totalWeightedExercises > 0
      ? Math.round((progressingExercises / totalWeightedExercises) * 25)
      : 0;

  // --- Completion Rate Score (0-25) ---
  const totalPlanned = scheduled.length || 1;
  const totalCompleted = scheduled.filter((s) => s.status === "completed").length;
  const completionScore = Math.round(
    Math.min(totalCompleted / totalPlanned, 1) * 25,
  );

  // --- Exercise Variety Score (0-25) ---
  const uniqueExercises = new Set(
    logs.map((l) => l.exercise_id ?? l.exercise_name),
  );
  // 15+ unique exercises in 4 weeks = max score
  const varietyScore = Math.round(Math.min(uniqueExercises.size / 15, 1) * 25);

  // --- Consistency Score (0-25) ---
  // How many of the 4 weeks had at least 1 workout logged
  const weeksWithWorkouts = new Set<number>();
  const now = new Date();
  for (const log of logs) {
    const logDate = new Date(log.date);
    const weekNum = Math.floor(
      (now.getTime() - logDate.getTime()) / (7 * 24 * 60 * 60 * 1000),
    );
    if (weekNum >= 0 && weekNum < 4) weeksWithWorkouts.add(weekNum);
  }
  const consistencyScore = Math.round((weeksWithWorkouts.size / 4) * 25);

  const totalScore =
    progressionScore + completionScore + varietyScore + consistencyScore;

  if (totalScore >= 70) return "advanced";
  if (totalScore >= 40) return "intermediate";
  return "beginner";
}

/**
 * Fetches all rows from a table with pagination to handle large datasets.
 *
 * The 1000-row ceiling is PostgREST's server-side `db-max-rows`, not a client
 * default — `.range()` cannot raise it (measured: requesting 0-1499 still
 * returns 1000). So PAGE_SIZE must stay <= 1000; a larger value would make the
 * first full page look short and end the loop early.
 *
 * `orderColumn` must be unique and immutable (a primary key). OI-79: Postgres
 * guarantees no row order without ORDER BY and PostgREST adds none, so an
 * unordered .range() loop can return overlapping or disjoint pages —
 * double-counting one user's workouts and missing another's.
 */
async function fetchAllRows<T>(
  supabaseClient: SupabaseClient,
  table: string,
  selectCols: string,
  dateColumn: string,
  dateGte: string,
  orderColumn: string,
): Promise<T[]> {
  const PAGE_SIZE = 1000;
  const allRows: T[] = [];
  let offset = 0;
  let hasMore = true;

  while (hasMore) {
    const { data, error } = await supabaseClient
      .from(table)
      .select(selectCols)
      .gte(dateColumn, dateGte)
      .order(orderColumn, { ascending: true })
      .range(offset, offset + PAGE_SIZE - 1);

    if (error) {
      throw new Error(`Failed to fetch ${table} at offset ${offset}: ${error.message}`);
    }

    if (data && data.length > 0) {
      allRows.push(...(data as T[]));
      offset += data.length;
      // If we got fewer rows than PAGE_SIZE, we've reached the end
      hasMore = data.length === PAGE_SIZE;
    } else {
      hasMore = false;
    }
  }

  return allRows;
}

/**
 * Injectable seam (coach workout parity 2, S0). Only the client factory goes
 * through `deps`; auth and telemetry stay direct calls (the adoption contracts
 * pin them as literal call sites).
 */
export interface WeeklyRecalcDeps {
  createClient: typeof createClient;
}

export const handler = async (
  req: Request,
  deps: WeeklyRecalcDeps = realDeps(),
): Promise<Response> => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  // ── Auth gate added 2026-07-26 (diagnose c3f8a1, Hermes L23/L24).
  //
  // This function shipped verify_jwt=false with NO authentication of any kind
  // while creating a SERVICE-ROLE client below — so any unauthenticated POST
  // from anywhere on the internet could drive a full-fleet recalculation over
  // every user. It escaped every guard because it is scheduled by nothing (zero
  // cron.job rows) and its client constant `weeklyRecalcFunction` is declared
  // but never invoked, so neither the cron registry nor any call-site grep saw
  // it — while `cron_auth_adoption_test.dart` omitted it and
  // `cron_telemetry_adoption_test.dart` listed it, the two hand-maintained
  // lists disagreeing about what it even is.
  //
  // Exactly the F44 shape: an unguarded verify_jwt=false service-role endpoint
  // invisible because no list covered it.
  if (!await isAuthorizedCronCall(req)) {
    console.warn(`[weekly-recalc] unauthorized caller; status=401`);
    return new Response(
      JSON.stringify({ error: "Unauthorized" }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  // OI-21 / audit-2026-05-29 EF-2: in-function execution telemetry so the
  // alert_edge_function_health cron (migrations 076/077) can SEE weekly-recalc
  // failures via cron_call_log. pg_cron's job_run_details only reflects the
  // net.http_post dispatch, not the EF's actual HTTP outcome.
  //
  // Placed AFTER the gate above — before it, an anonymous caller would get an
  // unauthenticated INSERT into public.cron_call_log (see _shared/cron_auth.ts).
  const logId = await logCronStart("weekly-recalc");

  try {
    const start = Date.now();

    // Cron-shaped job: service-role client, authorized by the CRON_SECRET gate
    // above rather than by a caller JWT.
    const supabaseClient = deps.createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // audit-2026-05-11 H-8 — 4-week window now IST-anchored so the
    // weekly recalc covers IST weeks not UTC weeks (5h30m drift
    // would mis-align with the user's actual training calendar).
    // L1b (plan B3): the window is exactly 28 IST dates ending today. The
    // summary rows are selected by `workout_log_id` (UUID v5 of each date,
    // `_shared/exercise_day.ts`), NOT by `completed_at` — that is the write
    // time, so an edited old log would sit inside a `completed_at` window while
    // belonging to a day outside it.
    const windowDates = istDatesEnding(28);
    const fourWeeksAgoStr = windowDates[0];
    const dayMap = await buildDayMap();
    const logIds = await windowLogIds(windowDates);

    // ── STEP 1: Bulk fetch ALL data in 2 parallel reads ──
    // Read from workout_log_exercises (per-exercise data) instead of workout_logs
    // (which now stores summary rows after sync refactor). All-user read:
    // `idx_wle_workout_log_id` serves the `.in("workout_log_id", ...)`.
    const [rawLogs, allScheduled, completedLogRows] = await Promise.all([
      fetchAllByIds<{ id: number | string; user_id: string; workout_log_id: string | null; exercise_id: string; exercise_name: string; set_number: number | null; is_pr: boolean | null; weight_kg: number | null; reps: number | null; completed_at: string; deleted_at: string | null }>(
        (chunk) =>
          supabaseClient
            .from("workout_log_exercises")
            // OI-246 follow-up (round-2 review finding P2, 2026-09-29): deleted_at
            // is selected so a deleted-and-tombstoned row can be excluded below
            // (migrations 150/151 suffix exercise_id on delete, which would
            // otherwise fragment the variety score and weight-progression
            // grouping). L1b adds id / workout_log_id / set_number for the
            // one-live-row-per-key rule and the day resolution.
            .select(
              "id, user_id, workout_log_id, exercise_id, exercise_name, set_number, is_pr, weight_kg, reps, completed_at, deleted_at",
            )
            .in("workout_log_id", chunk),
        logIds,
        { orderBy: "id", label: "weekly-recalc wle" }, // OI-79: PK — the only stable page key.
      ),
      fetchAllRows<ScheduledWorkout>(
        supabaseClient,
        "scheduled_workouts",
        "user_id, status, scheduled_date",
        "scheduled_date",
        fourWeeksAgoStr,
        "id", // OI-79: PK — scheduled_date repeats across users.
      ),
      // Completed days: `workout_logs` is the cloud mirror of `wlog_<date>`
      // (written by `markCompleted` only), the same set the client counts in
      // `completedWorkoutDayCount`. The floor for `total_workouts_done` comes
      // from here, never from exercise rows, so a partial day cannot lift it.
      // Same 28 IST dates as the window above (OI-492).
      // This read only feeds a floor that can RAISE the lifetime counter, so
      // its failure must not veto the tick (B-pass S1-F1): on error the map
      // is empty, `mergeMonotonicTotal` keeps every stored total, and the
      // experience levels are still written. Next Sunday raises the floor.
      fetchAllPages<{ id: number | string; user_id: string; date: string | null }>(
        () =>
          supabaseClient
            .from("workout_logs")
            .select("id, user_id, date")
            .gte("date", windowDates[0])
            .lte("date", windowDates[27]),
        { orderBy: "id", label: "weekly-recalc completed-days" },
      ).catch((err) => {
        console.error(
          `[weekly-recalc] completed-days read failed; total_workouts_done kept as stored this tick`,
          err,
        );
        return [] as Array<{ id: number | string; user_id: string; date: string | null }>;
      }),
    ]);
    const completedByUser = completedDayCounts(completedLogRows);

    // OI-246 follow-up (round-2 review finding P2) — exclude tombstoned rows
    // BEFORE deriving allLogs, so a deleted exercise log never reaches the
    // exercise-variety / weight-progression grouping below (see the fetch
    // comment above for why this matters specifically for this table).
    // L1b (B1/B3): then ONE live row per (user, day, exercise), in-window by
    // RESOLVED day, `date` = that day (not the write time).
    const liveRawLogs = liveLogsForWindow(excludeDeletedLogs(rawLogs), dayMap, windowDates);

    const allLogs: WorkoutLog[] = liveRawLogs;

    console.log(
      `weekly-recalc: fetched ${allLogs.length} logs, ${allScheduled.length} scheduled in ${Date.now() - start}ms`,
    );

    // ── STEP 2: Group by user_id in JavaScript ──
    const logsByUser = new Map<string, WorkoutLog[]>();
    for (const log of allLogs) {
      const list = logsByUser.get(log.user_id);
      if (list) {
        list.push(log);
      } else {
        logsByUser.set(log.user_id, [log]);
      }
    }

    const scheduledByUser = new Map<string, ScheduledWorkout[]>();
    for (const sw of allScheduled) {
      const list = scheduledByUser.get(sw.user_id);
      if (list) {
        list.push(sw);
      } else {
        scheduledByUser.set(sw.user_id, [sw]);
      }
    }

    // Merge all user IDs from both maps (a user might have logs but no schedule, or vice versa)
    const allUserIds = new Set<string>([
      ...logsByUser.keys(),
      ...scheduledByUser.keys(),
    ]);

    console.log(
      `weekly-recalc: grouped data for ${allUserIds.size} users in ${Date.now() - start}ms`,
    );

    // ── STEP 3: Calculate experience level for each user locally ──
    const levels = new Map<string, string>();
    const workoutCounts = new Map<string, number>();

    for (const userId of allUserIds) {
      const userLogs = logsByUser.get(userId) || [];
      const userScheduled = scheduledByUser.get(userId) || [];

      const level = calculateExperienceLevel(userLogs, userScheduled);
      levels.set(userId, level);
      // Distinct COMPLETED days (workout_logs.date), not exercise rows and not
      // partial days: see completedLogRows above.
      workoutCounts.set(userId, completedByUser.get(userId) ?? 0);
    }

    console.log(
      `weekly-recalc: calculated levels for ${levels.size} users in ${Date.now() - start}ms`,
    );

    // ── STEP 4: Batch UPDATE in chunks of 100 concurrent upserts ──
    const BATCH_SIZE = 100;
    const userIds = Array.from(allUserIds);
    let processed = 0;
    let errors = 0;
    const nowIso = new Date().toISOString();

    // Diagnose 3a7b9f (2026-05-27, c2 audit finding): `total_workouts_done`
    // is a LIFETIME monotonic counter incremented by client at workout
    // completion (train_provider.dart:1420). Pre-fix this cron overwrote
    // it with the count of distinct dates from the LAST 4 WEEKS of
    // workout_log_exercises (recompute window at line 174-176 + line 251).
    // For any user who trained more than 4 weeks ago, the recalc would
    // silently DECREASE their lifetime counter every Sunday. Defense:
    // pre-fetch existing values and apply GREATEST in the upsert payload.
    // Same monotonic-field-recompute class as the rank demotion fix.
    // OI-79 round-2: this read destructured `data` but NOT `error`, so a failed
    // query coerced to `rows ?? []`, `existingProgress` stayed EMPTY, and the
    // GREATEST guard directly below had nothing to compare against — silently
    // re-opening diagnose 3a7b9f (every user's LIFETIME total_workouts_done
    // overwritten with a 4-week count each Sunday). The defense against a
    // monotonic demotion was itself unguarded.
    //
    // Truncation was never the risk here — BATCH_SIZE=100 against a
    // one-row-per-user table is 100 rows — so this is routed through
    // fetchAllByIds for its THROW-on-error semantics, not for paging. A
    // failure now reaches the outer catch, the tick is recorded failed, and
    // next Sunday retries, instead of quietly demoting every user.
    const progressRows = await fetchAllByIds<Record<string, unknown>>(
      (chunk) =>
        supabaseClient
          .from("user_progress")
          .select("user_id, total_workouts_done")
          .in("user_id", chunk),
      userIds,
      { orderBy: "id", chunkSize: BATCH_SIZE, label: "weekly-recalc existing-progress" },
    );
    const existingProgress = new Map<string, number>();
    for (const row of progressRows) {
      existingProgress.set(
        row.user_id as string,
        (row.total_workouts_done as number | null) ?? 0,
      );
    }

    for (let i = 0; i < userIds.length; i += BATCH_SIZE) {
      const chunk = userIds.slice(i, i + BATCH_SIZE);

      const results = await Promise.all(
        chunk.map((userId) => {
          const recomputed = workoutCounts.get(userId) || 0;
          const existing = existingProgress.get(userId) || 0;
          const monotonicTotal = mergeMonotonicTotal(recomputed, existing);
          return supabaseClient
            .from("user_progress")
            .upsert(
              {
                user_id: userId,
                detected_experience_level: levels.get(userId),
                experience_last_calculated: nowIso,
                total_workouts_done: monotonicTotal,
              },
              { onConflict: "user_id" },
            )
            .then((res) => ({ userId, error: res.error }));
        }),
      );

      for (const result of results) {
        if (result.error) {
          console.error(
            `Failed to update experience for user ${result.userId}:`,
            result.error,
          );
          errors++;
        } else {
          processed++;
        }
      }
    }

    const totalTime = Date.now() - start;
    console.log(
      `weekly-recalc: processed ${processed} users, ${errors} errors in ${totalTime}ms`,
    );

    const status = errors === 0 ? "success" : (errors > processed ? "failed" : "partial");
    const httpStatus = errors > processed ? 500 : 200;
    await logCronEnd(logId, httpStatus >= 400 ? "failed" : "success", {
      httpStatus,
      errorSummary: errors > 0 ? `${errors} user-update errors` : undefined,
    });
    return new Response(
      JSON.stringify({
        status,
        users_processed: processed,
        errors,
        total_users: allUserIds.size,
        total_logs: allLogs.length,
        total_scheduled: allScheduled.length,
        duration_ms: totalTime,
      }),
      {
        status: httpStatus,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  } catch (err) {
    // Sanitised 5xx: never leak raw exception / SQL text.
    const requestId = crypto.randomUUID().split("-")[0];
    console.error(`[weekly-recalc] request_id=${requestId}`, err);
    await logCronEnd(logId, "failed", {
      httpStatus: 500,
      requestId,
      errorSummary: String(err),
    });
    return new Response(
      JSON.stringify({ error: "Internal server error", request_id: requestId }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  }
};

/** The production wiring: the real function itself (no call text here). */
export function realDeps(): WeeklyRecalcDeps {
  return { createClient };
}

if (import.meta.main) {
  // Wrapped, not `serve(handler)`: serve's Handler passes `(req, connInfo)`
  // and handler's second parameter is deps.
  serve((req) => handler(req));
}

// supabase/functions/_shared/ist_date.ts
// IST (UTC+5:30) date helpers shared across Edge Functions.
// Mirrors lib/core/utils/ist_date.dart on the Flutter client so both sides
// agree on what "today" means.

export const IST_OFFSET_MS = (5 * 60 + 30) * 60 * 1000;

/// Returns a new Date object shifted to IST (UTC+5:30).
export function istNow(d: Date = new Date()): Date {
  return new Date(d.getTime() + IST_OFFSET_MS);
}

/// Returns 'YYYY-MM-DD' in IST.
export function istDateStr(d: Date = new Date()): string {
  const ist = istNow(d);
  return ist.toISOString().substring(0, 10);
}

/// Returns day-of-week in IST (Sun=0 .. Sat=6).
/// Mirrors JavaScript's getDay() but computed in IST, not the server's local TZ.
export function istDayOfWeek(d: Date = new Date()): number {
  return istNow(d).getUTCDay();
}

/// Returns IST midnight (00:00:00 IST) for the given date as a
/// timestamptz-comparable ISO string carrying the +05:30 offset.
/// Use this for cloud rate-limit / cap queries like
/// `.gte("created_at", istDayStartIso())` so the "today" window
/// aligns with the user's IST day instead of UTC midnight (a 5h30m
/// drift that gives Indian users a stale rate-limit reset at
/// 05:30 IST every morning).
///
/// audit-2026-05-11 H-4 / H-10 — ai-proxy + ai-media-proxy vision
/// caps + free-tier message count were filtering against UTC
/// midnight; switched to this helper.
export function istDayStartIso(d: Date = new Date()): string {
  return `${istDateStr(d)}T00:00:00+05:30`;
}

const ONE_DAY_MS = 24 * 60 * 60 * 1000;

/** Yesterday's IST day as an [yStart, tStart) instant window, plus its IST date label. */
export function istYesterdayWindow(
  now: Date = new Date(),
): { yStart: string; tStart: string; label: string } {
  const tStartMs = Date.parse(istDayStartIso(now));
  const yStartMs = tStartMs - ONE_DAY_MS;
  return {
    yStart: new Date(yStartMs).toISOString(),
    tStart: new Date(tStartMs).toISOString(),
    label: istDateStr(new Date(yStartMs)),
  };
}

/// Returns the IST midnight instant of the MONDAY that starts the IST week
/// containing `d`, as a timestamptz-comparable ISO string carrying the
/// +05:30 offset (same shape as istDayStartIso, one level up).
///
/// day-swapper-sync-load spec §5.3 — the day-swap allowance window is a
/// Monday-Sunday IST week, and this file had no Monday helper before this.
/// Sun=0 in istDayOfWeek's convention, so the offset back to the most recent
/// Monday is (dow + 6) % 7: Mon(1)->0, Tue(2)->1, ..., Sat(6)->5, Sun(0)->6.
export function istWeekStartIso(d: Date = new Date()): string {
  const dow = istDayOfWeek(d);
  const daysSinceMonday = (dow + 6) % 7;
  const mondayIst = new Date(istNow(d).getTime() - daysSinceMonday * ONE_DAY_MS);
  const mondayDateStr = mondayIst.toISOString().substring(0, 10);
  return `${mondayDateStr}T00:00:00+05:30`;
}

/**
 * cron_auth.ts — shared-secret auth gate for cron-dispatched Edge Functions.
 *
 * Rewritten 2026-07-26 (closes-diagnose: c3f8a1). See HISTORY at the bottom —
 * the two previous designs both failed in production, and the second failed
 * silently for roughly eight weeks.
 *
 * AUTH MODEL
 * ----------
 * A single opaque shared secret. The caller must present
 * `Authorization: Bearer <CRON_SECRET>`, where `CRON_SECRET` is an Edge
 * Function secret whose value also lives in the Vault row `cron_secret`, read
 * by `private.cron_get_secret()` and interpolated into every `cron.job`
 * command (migrations 107/108).
 *
 * WHY A SHARED SECRET RATHER THAN A JWT
 * -------------------------------------
 * This is machine-to-machine auth between pg_cron and the Edge runtime. There
 * is no user identity to carry, no claims to inspect and no delegation — a
 * signed token buys nothing here, and every JWT-shaped attempt has coupled the
 * gate to platform key management that then changed underneath it:
 *
 *   - Attempt 1 compared the token to `SUPABASE_SERVICE_ROLE_KEY`. Broke when
 *     the Vault copy and the env copy drifted (diagnose 5a65bd).
 *   - Attempt 2 verified the signature against `SUPABASE_JWT_SECRET` — a
 *     variable Supabase does not inject and **forbids creating**, because the
 *     platform reserves the `SUPABASE_` prefix for secret names. Unsatisfiable
 *     by construction; every cron call 401'd from the day it deployed.
 *
 * A string comparison has no such coupling. It is unaffected by the JWT
 * signing-key migration now underway on this project and by the deprecation of
 * `SUPABASE_ANON_KEY` / `SUPABASE_SERVICE_ROLE_KEY`.
 *
 * ⚠ THE SECRET IS THE ONLY GATE. Cron functions run `verify_jwt=false`, so
 * their URLs accept unauthenticated POSTs from anywhere and this comparison is
 * all that stands between the open internet and a privileged fan-out (push
 * sends, Gemini spend, storage deletion). `CRON_SECRET` must be long and
 * cryptographically random — `openssl rand -hex 32`. Never a memorable phrase.
 *
 * USAGE (per cron function)
 * -------------------------
 *   import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
 *
 *   Deno.serve(async (req) => {
 *     if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
 *     if (!await isAuthorizedCronCall(req)) {
 *       return new Response(JSON.stringify({ error: "Unauthorized" }), {
 *         status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 *       });
 *     }
 *     const logId = await logCronStart("<slug>");   // AFTER the gate — see below
 *     // ... handler body
 *   });
 *
 * ⚠ KEEP `logCronStart` AFTER THIS GATE. It is tempting to move it earlier so
 * that rejected calls leave a telemetry row — the 2026-07-26 batch considered
 * exactly that. Don't: on a `verify_jwt=false` endpoint it would hand every
 * anonymous caller an unauthenticated INSERT into `public.cron_call_log`.
 * Outage visibility is provided instead by `alert_cron_silence` (migration
 * 109), which alerts on the ABSENCE of successful runs and therefore needs no
 * writes from unauthenticated callers.
 */

/**
 * Constant-time string comparison.
 *
 * Both sides are hashed to a fixed 32-byte digest first, then compared with an
 * XOR-accumulate that always walks the full length. This leaks neither the
 * secret's length nor the position of the first differing byte, whereas a plain
 * `!==` short-circuits on the first mismatch and is measurable over enough
 * requests.
 *
 * Worth the few microseconds here specifically because this comparison is the
 * ONLY gate on 16 publicly-reachable endpoints (see the warning above), and the
 * secret in production is currently low-entropy by explicit accepted risk
 * (migration 107 header) — a weak secret plus a timing oracle is materially
 * worse than either alone.
 */
// Exported (review round 1 F11) so telegram-admin-bot's webhook-secret
// comparison — the ONLY gate on that publicly-reachable endpoint, same
// threat model as the 16+ cron-secret-gated endpoints this was written
// for — can reuse it instead of a bare `!==`.
export async function timingSafeEqual(a: string, b: string): Promise<boolean> {
  const enc = new TextEncoder();
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", enc.encode(a)),
    crypto.subtle.digest("SHA-256", enc.encode(b)),
  ]);
  const va = new Uint8Array(da);
  const vb = new Uint8Array(db);
  let diff = 0;
  for (let i = 0; i < va.length; i++) diff |= va[i] ^ vb[i];
  return diff === 0;
}

/**
 * True when the request carries `Authorization: Bearer <CRON_SECRET>`.
 *
 * False on a missing header, a malformed bearer, an unset `CRON_SECRET`, or any
 * mismatch. Never throws — safe to call without try/catch.
 */
export async function isAuthorizedCronCall(req: Request): Promise<boolean> {
  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    if (!authHeader.startsWith("Bearer ")) {
      console.warn("[cron_auth] missing or malformed Authorization header");
      return false;
    }
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length === 0) {
      console.warn("[cron_auth] empty bearer token");
      return false;
    }

    // Trimmed on BOTH sides. A trailing newline pasted into the dashboard
    // secret would otherwise reject every call with no visible reason.
    const cronSecret = (Deno.env.get("CRON_SECRET") ?? "").trim();
    if (cronSecret.length === 0) {
      console.warn(
        "[cron_auth] CRON_SECRET is unset — every cron call will be rejected. " +
          "Set it in Project Settings -> Edge Functions -> Secrets, matching " +
          "the `cron_secret` Vault row exactly.",
      );
      return false;
    }

    if (!await timingSafeEqual(token, cronSecret)) {
      console.warn("[cron_auth] bearer token does not match CRON_SECRET");
      return false;
    }

    return true;
  } catch (err) {
    // Defensive — never let the auth gate crash its caller.
    console.error("[cron_auth] unexpected error:", err);
    return false;
  }
}

/*
 * HISTORY
 * -------
 * 2026-05-11 (7ad0c4)  Gate introduced; 8 cron functions were publicly callable.
 * 2026-05-12 (audit P0) Vault `service_role_key` row was empty, so the header
 *                       went out as `Bearer null` → 401 on every tick, 12 jobs.
 * 2026-05-15 (5a65bd)  Env-equality check broke on Vault/env key drift. That
 *                       write-up proposed "replace the brittle env-equality
 *                       check with a JWT signature+role decode" as the
 *                       permanent class fix.
 * 2026-05-16           The class fix shipped. It depended on
 *                       `SUPABASE_JWT_SECRET`, which cannot exist. The fix
 *                       made the bug permanent instead of ending it.
 * 2026-07-26 (c3f8a1)  Discovered: ~8 weeks of total cron silence. Three
 *                       safeguards had failed together — telemetry sat behind
 *                       the failing gate, pg_cron reports `succeeded` for any
 *                       dispatch regardless of HTTP status, and the health
 *                       alert computed a rate from the table the failure kept
 *                       empty. Replaced with this shared-secret gate; the
 *                       `deno.land/x/jose` dependency is gone with it, closing
 *                       a remote-dep-rot risk this repo has already been bitten
 *                       by (feedback_mistake_remote_dep_rot).
 */

/**
 * cron_telemetry — per-invocation execution telemetry for cron Edge Functions.
 *
 * Closes audit 2026-05-17 / OI-15. Background: `cron.job_run_details.status='succeeded'`
 * only confirms the pg_cron-side `net.http_post()` dispatch succeeded; it does NOT
 * reflect the Edge Function's actual HTTP response. During the Vault drift incident
 * (2026-05-11..16 — retired root §19 entry #161, relocated to
 * `supabase/functions/CLAUDE.md`'s cron-auth pattern by the 2026-05-18 declutter),
 * pg_cron reported 1066 "succeeded" runs across a week while every single call returned
 * 401 server-side and zero work happened.
 *
 * Each cron Edge Function imports this helper and:
 *   1. Calls `logCronStart(name)` at the top of its `serve` handler → returns a row id.
 *   2. Calls `logCronEnd(id, status, httpStatus?, errorSummary?)` before returning.
 *
 * The row lands in `public.cron_call_log` (migration 068). Retention: 10 days (migration
 * 169), plus each function's newest success and newest row for good (migration 172), via
 * `public.cleanup_cron_call_log()`, which `db_maintenance_nightly` calls (069, 141, 144).
 *
 * Failures inside the telemetry call itself are SWALLOWED (try/catch + debug log).
 * Cron functions MUST NOT 500 because telemetry is broken.
 */

import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

type CronLogStatus = "success" | "failed";

let _adminClient: SupabaseClient | null = null;

function adminClient() {
  if (_adminClient) return _adminClient;
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    // Edge runtime quirk — should never happen in prod, but don't crash if it does.
    return null;
  }
  _adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
  return _adminClient;
}

/**
 * Insert a `started` row. Returns the row id so the caller can update on exit.
 *
 * Returns `null` if telemetry insert fails — callers should pass that null straight
 * back into `logCronEnd` (which is a no-op on null id). The function itself never
 * throws.
 */
export async function logCronStart(functionName: string): Promise<number | null> {
  try {
    const supabase = adminClient();
    if (!supabase) return null;
    const { data, error } = await supabase
      .from("cron_call_log")
      .insert({ function_name: functionName, status: "started" })
      .select("id")
      .single();
    if (error || !data) {
      console.warn(`[cron_telemetry] start insert failed for ${functionName}`, error);
      return null;
    }
    return (data as { id: number }).id;
  } catch (e) {
    console.warn(`[cron_telemetry] start exception for ${functionName}`, e);
    return null;
  }
}

/**
 * Update the row created by `logCronStart` with terminal status.
 *
 * Passes-through silently when `id` is null (i.e. start insert failed).
 */
export async function logCronEnd(
  id: number | null,
  status: CronLogStatus,
  opts?: { httpStatus?: number; requestId?: string; errorSummary?: string },
): Promise<void> {
  if (id == null) return;
  try {
    const supabase = adminClient();
    if (!supabase) return;
    const patch: Record<string, unknown> = { status };
    if (opts?.httpStatus !== undefined) patch.http_status = opts.httpStatus;
    if (opts?.requestId) patch.request_id = opts.requestId;
    if (opts?.errorSummary) {
      // Cap error summary at 1000 chars to avoid bloat from giant stack traces.
      patch.error_summary = opts.errorSummary.slice(0, 1000);
    }
    const { error } = await supabase
      .from("cron_call_log")
      .update(patch)
      .eq("id", id);
    if (error) {
      console.warn(`[cron_telemetry] end update failed for id=${id}`, error);
    }
  } catch (e) {
    console.warn(`[cron_telemetry] end exception for id=${id}`, e);
  }
}

/**
 * paged_fetch — bounded reads for cron Edge Functions (OI-79).
 *
 * ## The bug this exists to prevent
 *
 * PostgREST caps every response at `db-max-rows` (1000 on this project) and
 * **supabase-js gives you no way to notice**. Measured live 2026-08-01 against
 * `dedsavbjuwgarrhphgnl`, `food_database` (1431 rows):
 *
 * | request                                   | status | Content-Range | rows |
 * |-------------------------------------------|--------|---------------|------|
 * | `?select=id` (what `.select()` sends)      | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 0-1499`                            | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 1000-1999`                         | 200 OK | `1000-1430/*` |  431 |
 * | `Prefer: count=exact`                      | 206    | `0-999/1431`  | 1000 |
 *
 * Three things follow, and each one is load-bearing:
 *
 * 1. **It is a 200, not a 206.** OI-79 was filed saying truncation shows up as
 *    `206 Partial Content`. That is only true when the caller asks for a count,
 *    and no cron function here does. In the shape our code actually sends, the
 *    response is a plain `200 OK` with a short body and `error === null`. There
 *    is no status, no error, and no total (`/*`) to compare against — a
 *    truncated read is *byte-for-byte indistinguishable* from a small one. The
 *    only signal is the row count, and it is AMBIGUOUS: a page shorter than
 *    `pageSize` means either end-of-data or a server cap below `pageSize`.
 *    That is why the loop terminates on an EMPTY page, never a short one.
 * 2. **`.range()` cannot raise the cap.** Asking for 0-1499 still yields 1000.
 *    So `pageSize` MUST be <= the cap; a larger value does not fetch more, it
 *    silently breaks the loop (you ask for 1500, get 1000, read that as a short
 *    page, and stop early — dropping every row after the first page).
 * 3. **Paging past the cap works.** Offset 1000-1999 returns the remainder.
 *    A `.range()` loop is therefore a real fix, not a workaround.
 *
 * ## Why `orderBy` is required and has no default
 *
 * Postgres guarantees no row order without an `ORDER BY`, and PostgREST adds
 * none. Two `.range()` calls against an unordered relation may return
 * overlapping or disjoint slices, so a paginated loop without a stable sort key
 * can **duplicate or skip rows** — silently, and only under load. Three loops in
 * this repo shipped that way (`morning-alert`, `weekly-recap-ready`,
 * `weekly-recalc`); `i-see-you-callout` got it right with
 * `.order("id", { ascending: true })`. Making `orderBy` a required parameter
 * with no default is how that mistake becomes unconstructible here.
 *
 * Pick a key that is **unique and immutable** — a primary key. A non-unique key
 * (`date`, `status`) does not fully order the rows, so ties can shuffle between
 * page requests and reintroduce the same skip/duplicate bug.
 *
 * ## RPCs
 *
 * `.order()` / `.range()` are accepted on `/rpc/` set-returning functions, so
 * both helpers work with `() => supabase.rpc(...)`. Whether `db-max-rows` also
 * caps RPC responses could not be settled from here: the only anon-executable
 * set-returning functions on this project are not `SECURITY DEFINER`, so RLS
 * returns 0 rows to `anon` and the probe is inconclusive. It does not change
 * anything — these helpers page unconditionally, which is correct either way
 * (if the cap does not apply, the loop simply ends on the first empty page).
 *
 * @see docs/audit/open_issues.md OI-79
 */

// deno-lint-ignore-file no-explicit-any

/**
 * PostgREST's server-side `db-max-rows` for this project, confirmed live
 * (table above). A response can never exceed this many rows regardless of the
 * requested `Range`.
 */
export const POSTGREST_MAX_ROWS = 1000;

/** Default page size. Sits at the cap: the largest value that is still safe. */
export const DEFAULT_PAGE_SIZE = 1000;

/**
 * Default `.in()` chunk size. Bounds the **request URL**, which is a different
 * constraint from `pageSize` (which bounds the *response*). A uuid costs ~37
 * bytes in `in.(...)`, so 100 ids is ~3.7KB and stays clear of the ~4-8KB URL
 * limits proxies impose. Matches the existing `BATCH_SIZE = 100` precedent in
 * `evaluate-rank-promotions`.
 */
export const DEFAULT_CHUNK_SIZE = 100;

/**
 * Runaway guard. At the default page size this permits 10M rows, far beyond any
 * legitimate cron scan — it exists to turn "PostgREST keeps returning full
 * pages forever" (an unstable sort key, a clock-skewed filter) into a loud
 * failure instead of an Edge Function that runs until the platform kills it.
 */
export const DEFAULT_MAX_PAGES = 10_000;

/** Minimal structural shape we need from a supabase-js query builder. */
interface RangeableBuilder {
  order(column: string, opts: { ascending: boolean }): RangeableBuilder;
  range(from: number, to: number): PromiseLike<{ data: unknown; error: unknown }>;
}

/** One ORDER BY term. */
export interface OrderKey {
  column: string;
  ascending?: boolean;
}

export interface PagedFetchOptions {
  /**
   * REQUIRED. Sort key — must be unique and immutable (a primary key). See the
   * header note on why this has no default.
   *
   * Pass an array to sort by several columns, e.g. to page a "most recent row
   * per user" read while preserving its ordering semantics:
   * `[{ column: "snapshot_date", ascending: false }, { column: "id" }]`.
   * The **last** term must be unique — the earlier ones can tie, and ties
   * without a unique tiebreaker are exactly the unstable-page bug.
   */
  orderBy: string | OrderKey[];
  /**
   * Sort direction for the single-column form. Ignored when `orderBy` is an
   * array (each term carries its own).
   */
  ascending?: boolean;
  /** Rows per request. MUST be <= {@link POSTGREST_MAX_ROWS}; see header note 2. */
  pageSize?: number;
  /** Runaway guard, see {@link DEFAULT_MAX_PAGES}. */
  maxPages?: number;
  /** Prefix for the saturation log line. Defaults to "paged_fetch". */
  label?: string;
}

/** Normalises the `orderBy` union into a non-empty list of ORDER BY terms. */
function orderKeys(opts: PagedFetchOptions): OrderKey[] {
  const bad = () => {
    throw new Error(
      "paged_fetch: `orderBy` is required and must be a non-empty column name " +
        "(or a non-empty array of them). A .range() loop without a stable sort " +
        "key can skip or duplicate rows (OI-79).",
    );
  };

  if (typeof opts.orderBy === "string") {
    if (!opts.orderBy.trim()) bad();
    return [{ column: opts.orderBy, ascending: opts.ascending ?? true }];
  }
  if (!Array.isArray(opts.orderBy) || opts.orderBy.length === 0) bad();
  const keys = (opts.orderBy as OrderKey[]).map((k) => {
    if (!k || typeof k.column !== "string" || !k.column.trim()) bad();
    return { column: k.column, ascending: k.ascending ?? true };
  });
  return keys;
}

function validate(opts: PagedFetchOptions): { pageSize: number; maxPages: number } {
  orderKeys(opts); // throws when the sort key is missing or malformed
  const pageSize = opts.pageSize ?? DEFAULT_PAGE_SIZE;
  if (!Number.isInteger(pageSize) || pageSize < 1) {
    throw new Error(`paged_fetch: pageSize must be a positive integer, got ${pageSize}`);
  }
  if (pageSize > POSTGREST_MAX_ROWS) {
    throw new Error(
      `paged_fetch: pageSize ${pageSize} exceeds PostgREST's db-max-rows ` +
        `(${POSTGREST_MAX_ROWS}). A larger page cannot fetch more rows — the server ` +
        `silently clamps it — so every page costs a full round-trip for at most ` +
        `${POSTGREST_MAX_ROWS} rows while the arithmetic implies more. The loop itself is ` +
        `SAFE at any cap (it advances by rows received and stops only on an empty page), ` +
        `so this is a wrong-configuration guard, not a correctness one. ` +
        `Use a pageSize <= ${POSTGREST_MAX_ROWS} (OI-79).`,
    );
  }
  const maxPages = opts.maxPages ?? DEFAULT_MAX_PAGES;
  if (!Number.isInteger(maxPages) || maxPages < 1) {
    throw new Error(`paged_fetch: maxPages must be a positive integer, got ${maxPages}`);
  }
  return { pageSize, maxPages };
}

/**
 * Reads **every** row matching a query, paging until an EMPTY page arrives.
 *
 * `makeQuery` must return a fresh builder each call — supabase-js builders are
 * single-use thenables, so reusing one across pages does not work. Apply your
 * filters there and let this apply `.order()` and `.range()`:
 *
 * ```ts
 * const rows = await fetchAllPages<{ user_id: string }>(
 *   () => supabase.from("coach_memory").select("user_id").gte("dropout_risk_score", 0.5),
 *   { orderBy: "user_id", label: "re-engagement path A" },
 * );
 * ```
 *
 * Throws on the first page error rather than returning partial rows. That is
 * deliberate: silently proceeding with an incomplete candidate set is the exact
 * failure this module exists to prevent, and a cron tick that cannot read its
 * inputs should fail loudly and retry on the next tick.
 */
export async function fetchAllPages<T>(
  makeQuery: () => unknown,
  opts: PagedFetchOptions,
): Promise<T[]> {
  const { pageSize, maxPages } = validate(opts);
  const keys = orderKeys(opts);
  const label = opts.label ?? "paged_fetch";
  const keyDesc = keys.map((k) => `${k.column}${k.ascending ? "" : " desc"}`).join(", ");

  const all: T[] = [];

  for (let page = 0; ; page++) {
    if (page >= maxPages) {
      throw new Error(
        `paged_fetch[${label}]: exceeded maxPages=${maxPages} (${all.length} rows read). ` +
          `Every page came back full — check that orderBy='${keyDesc}' ends in a unique, ` +
          `immutable column; an unstable sort key can loop forever.`,
      );
    }

    // Offset by rows ACTUALLY received, never by `page * pageSize`. The two
    // agree only while the server serves full pages, and `db-max-rows` is a
    // dashboard setting (Settings -> API -> Max rows), not a platform
    // invariant. Lower it to 500 and the old arithmetic broke completely:
    // page 0 asked 0-999, got 500, and `500 < pageSize` read as end-of-data —
    // so every one of the reads this module was written to fix would silently
    // return 500 rows with error === null. Advancing by `all.length` makes the
    // loop correct for ANY server cap without having to know what it is.
    const from = all.length;
    const to = from + pageSize - 1;

    let q = makeQuery() as RangeableBuilder;
    for (const k of keys) q = q.order(k.column, { ascending: k.ascending ?? true });
    const builder = q.range(from, to);

    const { data, error } = await builder;
    if (error) {
      throw new Error(
        `paged_fetch[${label}]: page ${page} (rows ${from}-${to}) failed: ` +
          `${(error as { message?: string } | null)?.message ?? String(error)}`,
      );
    }

    const rows = (data ?? []) as T[];
    all.push(...rows);

    // Only an EMPTY page proves end-of-data. A SHORT page does not: it is
    // equally the signature of a server cap below `pageSize` (see the offset
    // note above), and treating it as "done" is exactly the silent truncation
    // this module exists to prevent.
    //
    // COST, stated honestly. For `fetchAllPages` this is one extra round-trip
    // per read. For `fetchAllByIds` it is one extra per CHUNK, and with
    // DEFAULT_CHUNK_SIZE = 100 a chunk essentially never fills a 1000-row
    // page — so the confirming request lands on ~every chunk, not on a rare
    // boundary. 12 chunked call sites; at ~10k PRO users protein-gap-alert
    // goes from roughly 300 to 600 sequential round-trips per tick. Accepted
    // deliberately: these are daily cron jobs where wall-clock is cheap, and
    // the alternative is a read that silently returns half its rows with
    // error === null. If round-trips ever become the constraint, learn the
    // server's real page size once per process instead. (Corrected after
    // round-2 review — the earlier note claimed "the same one the
    // exact-multiple case already paid", true of fetchAllPages and NOT of the
    // chunked path that dominates.)
    if (rows.length === 0) break;
  }

  return all;
}

/**
 * Reads every row for a set of ids, chunking the `.in()` list **and** paging
 * within each chunk.
 *
 * Chunking alone is not enough, and that distinction is the whole point of this
 * function. `evaluate-rank-promotions` already had a `fetchInChunks` helper that
 * split `userIds` into batches of 100 — but a chunk bounds the *request*, not
 * the *response*. One 100-id chunk against a table holding N rows per user
 * returns 100xN rows, so it truncates at 10 rows/user no matter how small the
 * chunk is. This pages inside each chunk, which bounds both.
 *
 * ```ts
 * const logs = await fetchAllByIds<{ user_id: string }>(
 *   (chunk) => supabase.from("nutrition_logs")
 *                      .select("user_id, total_protein")
 *                      .eq("date", todayIST)
 *                      .in("user_id", chunk),
 *   proUserIds,
 *   { orderBy: "id", label: "protein-gap-alert nutrition" },
 * );
 * ```
 */
export async function fetchAllByIds<T>(
  makeQuery: (idChunk: string[]) => unknown,
  ids: string[],
  opts: PagedFetchOptions & { chunkSize?: number },
): Promise<T[]> {
  validate(opts);

  const chunkSize = opts.chunkSize ?? DEFAULT_CHUNK_SIZE;
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new Error(`paged_fetch: chunkSize must be a positive integer, got ${chunkSize}`);
  }

  if (ids.length === 0) return [];

  const all: T[] = [];
  for (let i = 0; i < ids.length; i += chunkSize) {
    const chunk = ids.slice(i, i + chunkSize);
    const rows = await fetchAllPages<T>(() => makeQuery(chunk), {
      ...opts,
      label: `${opts.label ?? "paged_fetch"} chunk@${i}`,
    });
    all.push(...rows);
  }
  return all;
}

// OI-246 follow-up (round-2 review finding P2, 2026-09-29). Extracted pure
// so it is independently testable without a live Supabase call -- mirrors
// workout-window-closing/deleted_template_filter.ts's shape for the same
// reason: the main handler is not unit-tested at the Deno level, so this is
// the only piece of the delete-filter logic a `deno test` can exercise.
//
// Why this exists: migrations 150/151 mutate `exercise_id` on the delete
// transition (suffix it, to free the natural key for a re-log — see
// docs/diagnoses/2026-09-28-exlog-tombstone-resurrection-e1c8b4.md). Before
// this filter, weekly-recalc's `calculateExperienceLevel` grouped rows by
// `exercise_id ?? exercise_name` with no `deleted_at` check at all, so a
// deleted-and-tombstoned row fragmented into its own bogus single-entry
// "exercise" (inflating the variety score) instead of being excluded, or —
// pre-150/151 — at least merging correctly into its real exercise's bucket
// (an existing minor inaccuracy, but not a fragmentation bug).

/** The shape this module reads off a `workout_log_exercises` row. */
export interface LiveLogRef {
  deleted_at: string | null;
}

/**
 * Keeps only rows that are NOT soft-deleted (migration 150's `deleted_at`).
 * A deleted exercise log must never reach the variety/weight-progression
 * scoring — it is neither "the user did this exercise" nor a valid grouping
 * key once its `exercise_id` may carry a delete-transition suffix.
 */
export function excludeDeletedLogs<T extends LiveLogRef>(
  rows: readonly T[],
): T[] {
  return rows.filter((r) => r.deleted_at == null);
}

// ── L1b (plan B1/B3) ─────────────────────────────────────────────────────────
import { inWindow, resolveDay } from "../_shared/exercise_day.ts";
import { liveSummaryRows, type SummaryRow } from "../_shared/live_exercise_rows.ts";

/**
 * One live summary row per (user, workout_log_id, exercise_id), kept only when
 * its RESOLVED workout day is in `dates`, with `date` = that day. The progression
 * and variety scores therefore see each exercise-day once (a superseded row
 * would double-count it) and an edited-old / rescheduled-forward log lands on
 * its own day, not on its write time.
 */
export function liveLogsForWindow<T extends SummaryRow>(
  rows: readonly T[],
  dayMap: Map<string, string>,
  dates: string[],
): Array<T & { date: string }> {
  return liveSummaryRows([...rows], dayMap)
    .filter((r) => inWindow(r, dayMap, dates))
    .map((r) => ({ ...r, date: resolveDay(r, dayMap) as string }));
}

// supabase/functions/_shared/exercise_day.ts
//
// Day attribution for `workout_log_exercises` (wle) summary rows (L1b plan B3).
//
// A wle row's DAY is carried only by `workout_log_id` = UUID v5 of
// `workout_<IST date>` (uuid_v5.ts). `completed_at` is the WRITE time: an old
// log edited today carries today's `completed_at` and an old id, and a log the
// coach moved forward keeps an earlier `completed_at` than its day. So no
// `completed_at` range selects a day window correctly; readers select by id
// (`windowLogIds`) and attribute by `resolveDay`.
//
// `_shared/ist_date.ts` is deliberately not edited (its bundle is imported by
// many functions); the helpers here only compose it.

import { istDateStr, IST_OFFSET_MS } from "./ist_date.ts";
import { workoutLogIdForDate } from "./uuid_v5.ts";

const ONE_DAY_MS = 24 * 60 * 60 * 1000;

/** First date the day map covers (earlier than any real log). */
export const DAY_MAP_START = "2020-01-01";
/** The map reaches this far past today: a coach reschedule moves logs forward. */
export const DAY_MAP_FUTURE_DAYS = 400;

/** `workout_log_id` an installed APK writes when it has no date: v5('workout_'). */
export const MISSING_DATE_BUCKET_ID_PROMISE = workoutLogIdForDate("");

/** `n` IST dates 'YYYY-MM-DD', ascending, the last one being IST today of `now`. */
export function istDatesEnding(n: number, now: Date = new Date()): string[] {
  if (!Number.isInteger(n) || n < 1) {
    throw new Error(`istDatesEnding: n must be a positive integer, got ${n}`);
  }
  const todayMs = Date.parse(`${istDateStr(now)}T00:00:00Z`);
  const out: string[] = [];
  for (let i = n - 1; i >= 0; i--) {
    out.push(istDateStr(new Date(todayMs - i * ONE_DAY_MS)));
  }
  return out;
}

/** The IST date after `date` ('YYYY-MM-DD'). */
export function nextIstDate(date: string): string {
  return istDateStr(new Date(Date.parse(`${date}T00:00:00Z`) + ONE_DAY_MS));
}

/**
 * Half-open instant window `[first date 00:00+05:30, day after last date 00:00+05:30)`
 * for a list of consecutive IST dates; both ends are UTC ISO strings.
 */
export function istDateWindow(dates: string[]): { start: string; end: string } {
  if (dates.length === 0) throw new Error("istDateWindow: empty date list");
  const first = dates[0];
  const last = dates[dates.length - 1];
  return {
    start: new Date(Date.parse(`${first}T00:00:00Z`) - IST_OFFSET_MS).toISOString(),
    end: new Date(Date.parse(`${nextIstDate(last)}T00:00:00Z`) - IST_OFFSET_MS).toISOString(),
  };
}

const dayMapCache = new Map<string, Promise<Map<string, string>>>();

/**
 * workout_log_id -> IST date for every date in [DAY_MAP_START, today + 400 days]
 * (~2,870 entries). Cached per process per `today`.
 */
export function buildDayMap(now: Date = new Date()): Promise<Map<string, string>> {
  const today = istDateStr(now);
  let cached = dayMapCache.get(today);
  if (!cached) {
    cached = (async () => {
      const startMs = Date.parse(`${DAY_MAP_START}T00:00:00Z`);
      const endMs = Date.parse(`${today}T00:00:00Z`) + DAY_MAP_FUTURE_DAYS * ONE_DAY_MS;
      const dates: string[] = [];
      for (let ms = startMs; ms <= endMs; ms += ONE_DAY_MS) {
        dates.push(istDateStr(new Date(ms)));
      }
      const ids = await Promise.all(dates.map((d) => workoutLogIdForDate(d)));
      const m = new Map<string, string>();
      ids.forEach((id, i) => m.set(id, dates[i]));
      return m;
    })();
    dayMapCache.clear(); // one live entry: yesterday's map is garbage after midnight
    dayMapCache.set(today, cached);
  }
  return cached;
}

/**
 * The `workout_log_id` values that select `dates` plus the missing-date bucket
 * (its rows are attributed by IST(completed_at) and window-filtered in memory).
 */
export async function windowLogIds(dates: string[]): Promise<string[]> {
  const ids = await Promise.all(dates.map((d) => workoutLogIdForDate(d)));
  ids.push(await MISSING_DATE_BUCKET_ID_PROMISE);
  return ids;
}

/** Splits `ids` into chunks of at most `size` (default 100, the PostgREST URL-safe size). */
export function chunkIds<T>(ids: T[], size = 100): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < ids.length; i += size) out.push(ids.slice(i, i + size));
  return out;
}

export interface DayBearingRow {
  workout_log_id?: string | null;
  completed_at?: string | null;
}

/**
 * The IST date a summary row belongs to: the date whose v5 id equals
 * `workout_log_id`; fallback IST(`completed_at`) for an unresolved id (the
 * missing-date bucket, a pre-2020 or far-future id); null when neither exists.
 */
export function resolveDay(row: DayBearingRow, dayMap: Map<string, string>): string | null {
  const viaId = row.workout_log_id ? dayMap.get(row.workout_log_id) : undefined;
  if (viaId) return viaId;
  if (row.completed_at) {
    const t = Date.parse(row.completed_at);
    if (!Number.isNaN(t)) return istDateStr(new Date(t));
  }
  return null;
}

/** True when `row` resolves to a day inside `dates` (inclusive list membership). */
export function inWindow(row: DayBearingRow, dayMap: Map<string, string>, dates: string[]): boolean {
  const d = resolveDay(row, dayMap);
  return d !== null && dates.includes(d);
}

// supabase/functions/_shared/uuid_v5.ts
//
// RFC 4122 UUID version 5 (SHA-1, name-based) over `crypto.subtle`, so no npm
// dependency and no import-map change (L1b plan B3, R3TA).
//
// Why this exists: the Flutter sync derives a workout session's cloud
// `workout_log_exercises.workout_log_id` as `Uuid().v5(SYNC_NAMESPACE,
// 'workout_<IST date>')` (`SyncService._deterministicId`,
// lib/core/services/sync_service.dart:663; `workoutLogIdForDate`). That id is
// the ONE field of a summary row that carries the workout's DAY — `completed_at`
// is the write time (an edited old log carries a recent one). Server readers
// therefore recompute the same ids to select a day window and to attribute a
// row to its day (`_shared/exercise_day.ts`).
//
// Parity is pinned by `uuid_v5_test.ts`: the RFC's own test vector, plus a real
// live `workout_log_id` and the date it was derived from.

/** `SyncService._syncNamespace` (lib/core/services/sync_service.dart:661). */
export const SYNC_NAMESPACE = "6ba7b810-9dad-11d1-80b4-00c04fd430c8";

function hexToBytes(hex: string): Uint8Array {
  const clean = hex.replace(/-/g, "");
  if (!/^[0-9a-fA-F]{32}$/.test(clean)) {
    throw new Error(`uuid_v5: not a UUID: ${hex}`);
  }
  const out = new Uint8Array(16);
  for (let i = 0; i < 16; i++) {
    out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function bytesToUuid(b: Uint8Array): string {
  const h = Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20, 32)}`;
}

/** UUID v5 of `name` (UTF-8) in `namespace`, lowercase hyphenated. */
export async function uuidV5(
  name: string,
  namespace: string = SYNC_NAMESPACE,
): Promise<string> {
  const ns = hexToBytes(namespace);
  const nameBytes = new TextEncoder().encode(name);
  const data = new Uint8Array(ns.length + nameBytes.length);
  data.set(ns, 0);
  data.set(nameBytes, ns.length);
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-1", data));
  const b = digest.slice(0, 16);
  b[6] = (b[6] & 0x0f) | 0x50; // version 5
  b[8] = (b[8] & 0x3f) | 0x80; // RFC 4122 variant
  return bytesToUuid(b);
}

/** The cloud `workout_log_id` of an IST date ('YYYY-MM-DD'), as the app writes it. */
export function workoutLogIdForDate(istDate: string): Promise<string> {
  return uuidV5(`workout_${istDate}`);
}

// supabase/functions/_shared/live_exercise_rows.ts
//
// `liveSummaryRows` — the ONE read-side rule for `workout_log_exercises` (wle)
// summary rows (L1b plan B1, SoT concept `wle_live_summary_read_contract`).
//
// `set_number` on wle is the set COUNT and part of the unique key, so an edit
// that changes the count leaves the old-count row live next to the new one
// (OI-307). After migration 155's `single_live` trigger there is one live row
// per (user, workout_log_id, exercise_id); this helper keeps the readers
// correct for rows written by older builds and for the window before the
// cleanup, and dedupes BEFORE any `is_pr` filter or cap.
//
// Winner = highest `set_number`, then highest `id` (the last push in 44/44 live
// groups, L1a-1 V11). The winner's OWN `is_pr` is used (last write wins).
// Known limit of any server rule: three rows A→B→A resolve to "highest count".

import { istDateStr } from "./ist_date.ts";

export interface SummaryRow {
  id?: string | number | null;
  user_id?: string | null;
  workout_log_id?: string | null;
  exercise_id?: string | null;
  set_number?: number | null;
  is_pr?: boolean | null;
  completed_at?: string | null;
  deleted_at?: string | null;
  // deno-lint-ignore no-explicit-any
  [k: string]: any;
}

function cmpId(a: SummaryRow["id"], b: SummaryRow["id"]): number {
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;
  const sa = String(a);
  const sb = String(b);
  const na = Number(sa);
  const nb = Number(sb);
  if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
  return sa < sb ? -1 : sa > sb ? 1 : 0;
}

function keyOf(r: SummaryRow, dayMap: Map<string, string> | undefined): string {
  const user = r.user_id ?? "";
  // Case-insensitive: the coach tools match exercise names with ilike, and the
  // same lift logged as "Bench Press" / "bench press" is one exercise-day.
  const ex = (r.exercise_id ?? "").toLowerCase();
  const resolved = r.workout_log_id && dayMap ? dayMap.get(r.workout_log_id) : undefined;
  if (resolved || !dayMap) {
    // Resolved id (or no map supplied: key on the id as stored).
    return `${user}|${r.workout_log_id ?? ""}|${ex}`;
  }
  // Unresolved id (missing-date bucket etc.): never collapse across days.
  let day = "";
  if (r.completed_at) {
    const t = Date.parse(r.completed_at);
    if (!Number.isNaN(t)) day = istDateStr(new Date(t));
  }
  return `${user}|~${day}|${ex}`;
}

/**
 * Drops tombstoned rows and keeps one winner per
 * (user_id, workout_log_id, exercise_id). Pass the day map from
 * `buildDayMap()` so rows whose id does not resolve are keyed by
 * (user, IST(completed_at) date, exercise) instead.
 */
export function liveSummaryRows<T extends SummaryRow>(
  rows: T[],
  dayMap?: Map<string, string>,
): T[] {
  const best = new Map<string, T>();
  for (const r of rows) {
    if (r.deleted_at) continue;
    const k = keyOf(r, dayMap);
    const cur = best.get(k);
    if (!cur) {
      best.set(k, r);
      continue;
    }
    const a = r.set_number ?? 0;
    const b = cur.set_number ?? 0;
    if (a > b || (a === b && cmpId(r.id, cur.id) > 0)) best.set(k, r);
  }
  return [...best.values()];
}

// supabase/functions/weekly-recalc/completed_days.ts
//
// Pure helpers for the `total_workouts_done` floor (coach workout parity 2,
// OI-492). The floor must come from COMPLETED days only: `workout_logs` is the
// cloud mirror of the client's `wlog_<date>` key, which only `markCompleted`
// writes, so a partial coach day (exercise rows, no `workout_logs` row) can
// never lift the lifetime counter.

import { countDistinctDates } from "../_shared/distinct_dates.ts";

/** Per user: the number of DISTINCT completed IST dates among `rows`. */
export function completedDayCounts(
  rows: ReadonlyArray<{ user_id: string; date?: string | null }>,
): Map<string, number> {
  const byUser = new Map<string, Array<{ date?: string | null }>>();
  for (const r of rows) {
    const list = byUser.get(r.user_id);
    if (list) list.push(r);
    else byUser.set(r.user_id, [r]);
  }
  const out = new Map<string, number>();
  for (const [userId, list] of byUser) out.set(userId, countDistinctDates(list));
  return out;
}

/**
 * `total_workouts_done` is a LIFETIME monotonic counter (diagnose 3a7b9f): the
 * 28-day recompute may raise it, never lower it.
 */
export function mergeMonotonicTotal(
  recomputed: number,
  existing: number | null | undefined,
): number {
  return Math.max(recomputed, existing ?? 0);
}

// supabase/functions/_shared/distinct_dates.ts
//
// ONE rule for "how many completed workout DAYS": the number of distinct
// `workout_logs.date` values, mirroring the client's
// `WorkoutReadService.completedWorkoutDayCount`
// (lib/core/services/workout_read_service.dart). `workout_logs` holds one row
// per completed day, plus a handful of dates that carry two rows (17 at the
// 2026-11-10 survey), so a ROW count over-counts those days.
//
// Used by evaluate-rank-promotions, weekly-recalc, getPromotionStatus and the
// i-see-you-callout Saturday gate, so the rule exists once (coach workout
// parity 2, OI-492).

/** `YYYY-MM-DD`, nothing else (no timestamp, no padding-free month). */
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Size of the Set of `date` strings that are non-empty after trim and match
 * `YYYY-MM-DD`. NULL, empty and malformed dates are ignored: these are
 * display-only counters, and a NULL-date row is a data defect, not a day.
 */
export function countDistinctDates(
  rows: ReadonlyArray<{ date?: string | null }>,
): number {
  const seen = new Set<string>();
  for (const r of rows) {
    const d = r?.date;
    if (typeof d !== "string") continue;
    const t = d.trim();
    if (t.length === 0 || !ISO_DATE.test(t)) continue;
    seen.add(t);
  }
  return seen.size;
}
